// Demonstração isolada: não acessa nem grava no Supabase.
const demoOrg={id:'demo-org',name:'Agrovantis · Demonstração'};
const demoSeed={clients:[{id:'demo-client',name:'Produtor Modelo',contact:'Contato fictício',email:'produtor@example.com'}],farms:[{id:'demo-farm',clientId:'demo-client',name:'Fazenda Horizonte · Fictícia',city:'Cruz Alta / RS'}],fields:[]};
for(let i=0;i<3;i++){const x=-53.65+i*.009,y=-28.61;const rings=[[[x,y],[x+.007,y],[x+.007,y+.008],[x,y+.008],[x,y]]];demoSeed.fields.push({id:'demo-field-'+i,farmId:'demo-farm',name:['Talhão Norte','Talhão Central','Talhão Sul'][i],rings,boundary:{type:'Polygon',coordinates:rings},area:60.8})}
const demoCampaigns=demoSeed.fields.map((f,i)=>({id:'demo-campaign-'+i,consultancy_id:demoOrg.id,field_id:f.id,name:'Diagnóstico de solo · Safra 2026/27',planned_date:'2026-10-18',depth_from_cm:0,depth_to_cm:20,notes:'DADOS FICTÍCIOS. Pontos ilustrativos para apresentar o registro de coletas; não constituem recomendação de densidade ou plano agronômico.'}));
const demoPoints=demoCampaigns.flatMap((c,i)=>Array.from({length:8},(_,j)=>({id:'demo-point-'+i+'-'+j,consultancy_id:demoOrg.id,campaign_id:c.id,code:'P'+String(j+1).padStart(3,'0'),latitude:-28.608+(j%4)*.0015,longitude:-53.648+i*.009+Math.floor(j/4)*.003,status:j<5?'collected':'planned',collected_on:j<5?'2026-10-18':null,notes:'Amostra demonstrativa'})));
const demoState={data:structuredClone(demoSeed),sampling_campaigns:structuredClone(demoCampaigns),sampling_points:structuredClone(demoPoints)};
boot=async function(){org=demoOrg;db=demoState.data;db.fields.forEach(f=>f.area=areaRing(f.rings[0]));document.querySelector('.notice').innerHTML='DEMONSTRAÇÃO · Fazenda e coordenadas fictícias · Alterações temporárias nesta aba. <a href="index.html">Voltar ao login</a>';document.querySelector('.asidefoot').innerHTML='BUILD 004 · DEMONSTRAÇÃO<br>Dados inteiramente fictícios';render()};
loadData=async function(){db=demoState.data;render()};
cloudWrite=async function(table,row,edit=false){const list=demoState.data[table];if(!list)throw Error('Cadastro indisponível na demonstração.');let old=list.find(x=>x.id===row.id);if(edit&&!old)throw Error('Cadastro não encontrado.');if(old)Object.assign(old,row);else list.push(structuredClone(row));return [row]};
cloudDelete=async function(table,id){demoState.data[table]=demoState.data[table].filter(x=>x.id!==id)};
request=async function(path,method='GET',body){const u=new URL(path,'https://demo.invalid');const table=u.pathname.split('/').pop();if(!['sampling_campaigns','sampling_points'].includes(table))throw Error('Esta operação exige o aplicativo conectado.');const matches=row=>Array.from(u.searchParams).every(([k,v])=>!v.startsWith('eq.')||String(row[k])===v.slice(3));const rows=demoState[table];if(method==='GET')return structuredClone(rows.filter(matches));if(method==='POST'){const row={...body,id:body.id||crypto.randomUUID()};rows.push(row);return [structuredClone(row)]}if(method==='PATCH'){const changed=rows.filter(matches);changed.forEach(r=>Object.assign(r,body));return structuredClone(changed)}if(method==='DELETE'){const removed=rows.filter(matches);demoState[table]=rows.filter(r=>!matches(r));return structuredClone(removed)}throw Error('Operação indisponível.');};
